  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chips, setChips] = useState<string[]>([]);
  const [input, setInput] = useState("");
  const [thinking, setThinking] = useState(false);
  const [building, setBuilding] = useState(false);
  const [error, setError] = useState("");
  const bottom = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const { messages, chips } = JSON.parse(saved) as { messages: ChatMessage[]; chips: string[] };
      setMessages(messages);
      setChips(chips);
      return;
    }
    void send([]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (messages.length) localStorage.setItem(STORAGE_KEY, JSON.stringify({ messages, chips }));
    bottom.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, chips, thinking]);

  async function send(history: ChatMessage[]) {
    setThinking(true);
    setError("");
    try {
      const turn = await api<Turn>("/api/intake", { method: "POST", body: JSON.stringify({ messages: history }) });
      const next = [...history, { role: "assistant" as const, content: turn.reply }];
      setMessages(next);
      setChips(turn.chips);
      if (turn.done && turn.profile) await build(turn.profile);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Something went wrong.");
    } finally {
      setThinking(false);
    }
  }

  async function build(profile: ParentProfile) {
    setBuilding(true);
    try {
      const { id } = await api<{ id: string }>("/api/registries", { method: "POST", body: JSON.stringify({ profile }) });
      localStorage.removeItem(STORAGE_KEY);
      router.push(`/registry/${id}/review`);
    } catch (e) {
      setBuilding(false);
      setError(e instanceof Error ? e.message : "Your registry couldn't be built. Try again.");
    }
  }

  function answer(text: string) {
    const trimmed = text.trim();
    if (!trimmed || thinking) return;
    const history = [...messages, { role: "user" as const, content: trimmed }];
    setMessages(history);
    setChips([]);
    setInput("");
    void send(history);
  }

  function restart() {
    localStorage.removeItem(STORAGE_KEY);
    setMessages([]);
    void send([]);
  }

  if (building) return <Building />;

  const answered = messages.filter((m) => m.role === "user").length;

  return (
    <div className="flex min-h-dvh flex-col pt-5">
      <header className="mb-8 flex items-center justify-between text-[13px]">
        <span className="text-muted">About {Math.max(1, 8 - answered)} questions left</span>
        <button onClick={restart} className="link">
          Start over
        </button>
      </header>

      <div className="flex-1 space-y-6" aria-live="polite">
        {messages.map((m, i) =>
          m.role === "user" ? (
            <div key={i} className="flex justify-end">
              <p className="max-w-[80%] rounded-2xl rounded-br-md bg-surface px-4 py-2.5">{m.content}</p>
            </div>
          ) : (
            <p key={i} className="max-w-[34ch] font-serif text-[19px] leading-relaxed">
              {m.content}
            </p>
          ),
        )}
        {thinking && <p className="font-serif text-[19px] text-muted">…</p>}
        {error && (
          <p role="alert" className="text-[14px] text-danger">
            {error}{" "}
            <button className="underline underline-offset-4" onClick={() => void send(messages)}>
              Try again
            </button>
          </p>
        )}
        <div ref={bottom} />
      </div>

      <div className="sticky bottom-0 -mx-4 space-y-3 bg-bg px-4 pt-4 pb-[max(1rem,env(safe-area-inset-bottom))] sm:-mx-6 sm:px-6">
        {chips.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {chips.map((chip) => (
              <button key={chip} className="chip" onClick={() => answer(chip)} disabled={thinking}>
                {chip}
              </button>
            ))}
          </div>
        )}
        <form
          onSubmit={(e) => {
            e.preventDefault();
            answer(input);
          }}
          className="flex gap-2"
        >
          <label htmlFor="chat-input" className="sr-only">
            Your answer
          </label>
          <input
            id="chat-input"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Or type your own answer"
            className="field"
          />
          <button className="btn-primary shrink-0" disabled={thinking || !input.trim()}>
            Send
          </button>
        </form>
      </div>
    </div>
  );
}

const BUILD_STEPS = CATEGORIES;
const STEP_MS = 3500;

/** The wait while the registry is built: a lamp warming up as each category gets filled. */
function Building() {
  const [step, setStep] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => setStep((s) => Math.min(s + 1, BUILD_STEPS.length - 1)), STEP_MS);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="relative flex min-h-dvh flex-col justify-center overflow-hidden">
      <div
        aria-hidden
        className="pointer-events-none absolute top-1/2 left-1/2 -z-0 h-[140vmin] w-[140vmin] -translate-x-1/2 -translate-y-1/2 rounded-full"
        style={{
          background: "radial-gradient(circle, rgb(237 190 116 / 0.22) 0%, rgb(237 190 116 / 0.06) 35%, transparent 65%)",
          animation: `lamp ${(BUILD_STEPS.length * STEP_MS) / 1000}s ease-out forwards`,
        }}
      />
      <div className="relative space-y-6">
        <h1 className="font-serif text-[33px] leading-tight font-semibold">Building your registry</h1>
        <p className="max-w-[40ch] text-muted">
          Choosing real products from Amazon, Target, and Walmart, and noting why each one is on your list. This takes
          about 30 seconds.
        </p>
        <ol className="space-y-1 font-serif text-[21px]" role="status">
          {BUILD_STEPS.map((name, i) => (
            <li
              key={name}
              className={`transition-colors duration-700 ${i < step ? "text-text" : i === step ? "text-accent" : "text-muted/40"}`}
            >
              {name}
              {i < step && <span className="sr-only"> done</span>}
            </li>
          ))}
        </ol>
      </div>
    </div>
  );
}

import "server-only";
import { getSupabaseAdmin, isSupabaseConfigured } from "./registry-store";

const LOCAL_OWNER_ID = "00000000-0000-0000-0000-000000000001";

export async function getOwnerId(request: Request): Promise<string | null> {
  if (!isSupabaseConfigured()) return LOCAL_OWNER_ID;
  const token = request.headers.get("authorization")?.replace(/^Bearer\s+/i, "");
  if (!token) return null;
  const { data, error } = await getSupabaseAdmin().auth.getUser(token);
  if (error || !data.user) return null;
  return data.user.id;
}

export function unauthorized() {
  return Response.json({ error: "Please sign in to continue." }, { status: 401 });
}

